```c
#include <unistd.h>
#include <fcntl.h>
#define BUFSIZE 4096
int main(void) {
int in_fd = open("input.txt", O_RDONLY);
int out_fd = open("output.txt", O_WRONLY | O_CREAT, 0644);
char buf[BUFSIZE];
int n;
while ((n = read(in_fd, buf, BUFSIZE)) > 0)
write(out_fd, buf, n);
close(in_fd);
close(out_fd);
return 0;
}
```

